#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> location={0,0.2,1.5,2.0};
vector<double> coreDistance={0.2,0.2,0.5,0.5};
for(int i=0;i<int(location.size());i++)
    for(int j=i+1;j<int(location.size());j++){
        double mutual=max(coreDistance[i],max(coreDistance[j],
            fabs(location[i]-location[j])));
        cout<<i<<" "<<j<<" mutual reachability "<<mutual<<endl;
    }
    return 0;
}

