#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> signal={0.02,0.04,-0.01,0.01};
vector<double> market={0.01,0.03,-0.02,0};
double mm=0,sm=0,cov=0,var=0;
for(int i=0;i<4;i++){mm+=market[i]/4;sm+=signal[i]/4;}
for(int i=0;i<4;i++){
    cov+=(market[i]-mm)*(signal[i]-sm);
    var+=pow(market[i]-mm,2);
}
double beta=cov/var,remainingCov=0;
for(int i=0;i<4;i++){
    double neutral=signal[i]-sm-beta*(market[i]-mm);
    remainingCov+=neutral*(market[i]-mm);
}
cout<<"Removed beta "<<beta<<" residual covariance "<<remainingCov<<endl;
    return 0;
}

